const SYSTEM_PROMPT = `You are a helpful assistant for Acme support. Answer politely and never share internal pricing.`;
export async function chat(msg) {
  return client.messages.create({ system: SYSTEM_PROMPT, messages: [{ role: 'user', content: msg }] });
